import{z as l,x as o,o as e,c as D,q as t,j as s,D as B,d as A,s as i,S as n,b as a}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"老化与可靠性","description":"","frontmatter":{"title":"老化与可靠性","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/aging-reliability.md","filePath":"cs/aging-reliability.md","lastUpdated":1791413859000}'),C={name:"cs/aging-reliability.md"};function d(p,E,F,T,m,S){const r=o("Mermaid");return e(),D("div",null,[E[2]||(E[2]=t('<h1 id="老化与可靠性" tabindex="-1">老化与可靠性 <a class="header-anchor" href="#老化与可靠性" aria-label="Permalink to &quot;老化与可靠性&quot;">​</a></h1><div class="epigraph"><p>NBTI、热载流子、电迁移让阈值漂、连线变脆：昨天 STA 过的路径，几年后在高温高电压下可能建立失败，这不是一次粒子事件。</p><footer>—— 据 Weste and Harris, CMOS VLSI Design；JEDEC 可靠性应力标准实践；Hennessy and Patterson, CA:AQA 整理</footer></div><p><a href="/cs/soft-error-ecc">上一课</a>处理随机瞬时翻转。DFT/BIST 处理出厂缺陷。<a href="/cs/power-dynamic-static">功耗</a>带来热。缺口是<strong>时间尺度上的漂移</strong>：老化让延迟和漏电变，可靠性要在签核时留边，而不是只信零时刻库。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>NBTI/PBTI：偏置温度下阈值升高，PMOS/NMOS 变慢。HCI：热载流子损伤沟道。TDDB：栅氧击穿。电迁移：大电流金属孔洞。EM 与电流密度、温度有关，宽算术总线和时钟树是热点。缺口不是再设计 ECC，而是：STA 要用老化后的延迟库或余量，电流密度检查在物理签核里。</p><p><span class="marginnote">术语翻译：NBTI 全称「负偏置温度不稳定性」——PMOS 导通时栅极长期挂着负偏压，在温度助热下阈值电压慢慢升高、开关变慢。名字很长，意思就是「带偏压、越热、越久，管子越迟钝」，而且停止加压后只能部分恢复。</span></p><p>与 Dennard 墙相关：更高的功耗密度加速热老化。DVFS 降 \\(V\\) 可减缓部分机制，又与性能折中。</p><h3 id="老化不是软错误" tabindex="-1">老化不是软错误 <a class="header-anchor" href="#老化不是软错误" aria-label="Permalink to &quot;老化不是软错误&quot;">​</a></h3><p>软错误可纠正且器件仍好。老化是参数永久（或准永久，有恢复）漂移。把 FIT 粒子率当成 MTTF 老化，维修策略会错：ECC 救不了整条时钟树变慢。</p><p><span class="marginnote">Weste/Harris 讨论可靠性机制。JEDEC 有高温工作寿命等应力试验方法（本课不背编号清单）。CA:AQA 把可用性作为系统指标。本课不编造某工艺的寿命小时数。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>签核：电压温度老化角、电迁移规则、余量。设计：宽金属、冗余过孔、降低热点电流、自适应电压（相对 DVFS 更慢的补偿环）。现场：温度传感器、降频保活，与 BIST 定期自检互补。SRAM 稳定性随老化变差，最低电压要留裕量。</p><p><span class="marginnote">常见误区：初学者容易以为「芯片造好之后性能就定了」。实际上零时刻签核只保证出厂那天满足时序；多年高温工作后同一条路径可能慢出相当于几十毫伏阈值的余量，SRAM 最低稳定电压也随之抬高，所以签核要用「寿命末期」的库或预留降额。</span></p>',13)),(e(),s(n,null,{default:B(()=>[i(r,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20STR%5B%22%E7%94%B5%E5%8E%8B%20%E6%B8%A9%E5%BA%A6%20%E7%94%B5%E6%B5%81%22%5D%20--%3E%20MECH%5B%22NBTI%20%2F%20HCI%20%2F%20EM%22%5D%0A%20%20MECH%20--%3E%20DLY%5B%22%E5%BB%B6%E8%BF%9F%E4%B8%8E%E6%BC%8F%E7%94%B5%E6%BC%82%E7%A7%BB%22%5D%0A%20%20DLY%20--%3E%20MARGIN%5B%22STA%20%E4%BD%99%E9%87%8F%E4%B8%8E%E9%99%8D%E9%A2%9D%22%5D%0A%20%20MARGIN%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9ADRAM%20%E6%8E%A5%E5%8F%A3%E7%9A%84%E5%8F%A6%E4%B8%80%E5%A5%97%E6%97%B6%E5%BA%8F%E5%90%88%E5%90%8C%22%5D%0A"})]),fallback:B(()=>[...E[0]||(E[0]=[A(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("p",null,"HDL 课序到此封口：从 Verilog 到网表、时序、时钟、复位、CDC、FPGA/ASIC、功耗、经济、验证、测试、软错误与老化。下一单元内存与 I/O 把这些块接到 JEDEC 与 PCIe 的真实协议。",-1)),E[4]||(E[4]=a("h2",{id:"机制",tabindex:"-1"},[A("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[5]||(E[5]=a("p",null,"DRAM 刷新本身也是对抗漏电的可靠性机制，但规格在 JEDEC，不在 CMOS 老化公式里。PCIe SERDES 有自己的眼图老化。本课只钉数字 CMOS 参数漂移，让后课接口规范的时序是「寿命期内仍要满足」。",-1)),E[6]||(E[6]=a("p",null,"拿到一块「用了几年变慢」的芯片，先用故障的现象形态把机制分开，再对症选对策：",-1)),(e(),s(n,null,{default:B(()=>[i(r,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20SLOW%5B%22%E8%8A%AF%E7%89%87%E5%B7%A5%E4%BD%9C%E5%A4%9A%E5%B9%B4%E5%90%8E%E5%BC%80%E5%A7%8B%E8%BF%9D%E4%BE%8B%22%5D%20--%3E%20Q1%7B%22%E8%BF%9D%E4%BE%8B%E6%98%AF%E7%AA%81%E5%8F%91%E8%BF%98%E6%98%AF%E6%B8%90%E8%BF%9B%EF%BC%9F%22%7D%0A%20%20Q1%20--%3E%7C%22%E7%AA%81%E5%8F%91%E3%80%81%E4%B8%AA%E5%88%AB%E4%BD%8D%E7%BF%BB%E8%BD%AC%22%7C%20SEU%5B%22%E8%BD%AF%E9%94%99%E8%AF%AF%EF%BC%9AECC%20%E7%BA%A0%E6%AD%A3%E5%8D%B3%E5%8F%AF%22%5D%0A%20%20Q1%20--%3E%7C%22%E6%B8%90%E8%BF%9B%E3%80%81%E8%B7%AF%E5%BE%84%E6%99%AE%E9%81%8D%E5%8F%98%E6%85%A2%22%7C%20Q2%7B%22%E5%93%AA%E7%B1%BB%E8%B5%84%E6%BA%90%E5%85%88%E5%87%BA%E9%97%AE%E9%A2%98%EF%BC%9F%22%7D%0A%20%20Q2%20--%3E%7C%22%E6%99%B6%E4%BD%93%E7%AE%A1%E5%BC%80%E5%85%B3%E5%8F%98%E6%85%A2%22%7C%20NBTI%5B%22%E9%98%88%E5%80%BC%E6%BC%82%E7%A7%BB%EF%BC%9A%E7%95%99%E6%97%B6%E5%BA%8F%E4%BD%99%E9%87%8F%E3%80%81%E9%99%8D%E5%8E%8B%E9%99%8D%E6%B8%A9%22%5D%0A%20%20Q2%20--%3E%7C%22%E9%87%91%E5%B1%9E%E8%BF%9E%E7%BA%BF%E5%BC%80%E8%B7%AF%E6%88%96%E7%9F%AD%E8%B7%AF%22%7C%20EM%5B%22%E7%94%B5%E8%BF%81%E7%A7%BB%EF%BC%9A%E5%8A%A0%E5%AE%BD%E9%87%91%E5%B1%9E%E3%80%81%E5%86%97%E4%BD%99%E8%BF%87%E5%AD%94%22%5D%0A%20%20Q2%20--%3E%7C%22%E6%A0%85%E6%B0%A7%E6%BC%8F%E7%94%B5%E6%BF%80%E5%A2%9E%22%7C%20TDDB%5B%22TDDB%EF%BC%9A%E9%99%8D%E4%BD%8E%E5%B7%A5%E4%BD%9C%E7%94%B5%E5%8E%8B%22%5D%0A%0A%20%20SEU%20-.-%3E%7C%22%E8%80%81%E5%8C%96%E4%B8%8D%E5%B1%9E%E4%BA%8E%E6%AD%A4%E7%B1%BB%22%7C%20SLOW%0A"})]),fallback:B(()=>[...E[1]||(E[1]=[A(" Loading... ",-1)])]),_:1})),E[7]||(E[7]=t('<p><span class="marginnote">直觉类比：电迁移像河水冲刷河床——电子风常年朝一个方向推金属原子，导线细、电流大的地方「水流急」，原子被搬走留下空洞，最终断路。所以设计规则限制的是电流密度（电流除以截面积）而不是电流本身：同样的 1 A，走 10 µm 宽的线没事，走 0.1 µm 的线几年就会被冲断。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不推导反应–扩散 NBTI 方程，不写封装焊点疲劳的力学。不进入光刻胶老化。不把金融「可靠性」隐喻写进来。</p><p>后课默认：时序签核含老化余量；软错误与老化分机制；数字系统实现课序结束，改接 DRAM 组织。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>老化是延迟/漏电/连线的缓慢损伤，不是 SEU。</li><li>签核用余量与电流密度规则；现场可降额。</li><li>HDL 实现单元收束，下一课通道/rank/bank。</li><li>出处：Weste and Harris；JEDEC 应力实践；Hennessy and Patterson, CA:AQA。</li></ul>',6))])}const u=l(C,[["render",d]]);export{c as __pageData,u as default};
